import {initAuth,onAuthStateChanged,signInWithEmailAndPassword,sendEmailVerification,signOut,reload,setPersistence,browserLocalPersistence,browserSessionPersistence} from './firebase-client.js';
const $=s=>document.querySelector(s);let auth=null;
function notice(text,error=false){$('#auth-notice').hidden=false;$('#auth-notice').textContent=text;$('#auth-notice').classList.toggle('error',error)}
$('#show-password').onclick=()=>{const input=$('#auth-form').elements.password;input.type=input.type==='password'?'text':'password';$('#show-password').textContent=input.type==='password'?'Show':'Hide'};
const message=e=>({'auth/invalid-credential':'The email or password is incorrect.','auth/too-many-requests':'Too many attempts. Please try again later.','auth/network-request-failed':'Connection failed. Check your internet and try again.','auth/operation-not-allowed':'Enable Email/Password sign-in in Firebase Authentication.'}[e.code]||'Could not complete the request. Please try again.');
$('#auth-form').onsubmit=async e=>{e.preventDefault();if(!auth)return;const b=$('#auth-submit');b.disabled=true;try{const f=e.currentTarget.elements,email=f.email.value.trim();await setPersistence(auth,f.remember.checked?browserLocalPersistence:browserSessionPersistence);await signInWithEmailAndPassword(auth,email,f.password.value);if(auth.currentUser.emailVerified)location.href='/admin.html';}catch(e){notice(message(e),true)}finally{b.disabled=false}};
$('#auth-signout').onclick=()=>signOut(auth);$('#resend').onclick=async()=>{try{await sendEmailVerification(auth.currentUser);notice('Verification email sent.')}catch(e){notice(message(e),true)}};$('#check-verified').onclick=async()=>{try{await reload(auth.currentUser);await auth.currentUser.getIdToken(true);if(auth.currentUser.emailVerified)location.href='/admin.html';else notice('Email is not verified yet. Open the verification link first.')}catch(e){notice(message(e),true)}};
try{auth=await initAuth();onAuthStateChanged(auth,user=>{const signed=!!user;$('#auth-form').hidden=signed;$('#account-state').hidden=!signed;if(user){$('#account-email').textContent=user.email;$('#verify-actions').hidden=user.emailVerified;$('#auth-title').textContent='Your account.';$('#auth-description').textContent=user.emailVerified?'Your email is verified.':'One more step: verify your email.'}else{$('#auth-title').textContent='Welcome back.';$('#auth-description').textContent='Sign in to your AquaVita account.';$('#auth-notice').hidden=true}})}catch(e){notice(e.message,true);$('#auth-submit').disabled=true;}
